PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS schema_migrations(version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY CHECK(id='local-owner'), display_name TEXT NOT NULL, preferences TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS projects(id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, name TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', goal TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'active', created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS items(id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, type TEXT NOT NULL, title TEXT NOT NULL, canonical_url TEXT, source TEXT NOT NULL, content TEXT NOT NULL DEFAULT '', summary TEXT NOT NULL DEFAULT '', personal_note TEXT NOT NULL DEFAULT '', reason TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'inbox', sensitivity TEXT NOT NULL DEFAULT 'normal', favorite INTEGER NOT NULL DEFAULT 0, project_id TEXT REFERENCES projects(id) ON DELETE SET NULL, metadata TEXT NOT NULL DEFAULT '{}', content_hash TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, archived_at TEXT, UNIQUE(user_id,canonical_url));
CREATE INDEX IF NOT EXISTS idx_items_owner_updated ON items(user_id,updated_at DESC);
CREATE INDEX IF NOT EXISTS idx_items_project ON items(project_id);
CREATE INDEX IF NOT EXISTS idx_items_hash ON items(user_id,content_hash);
CREATE TABLE IF NOT EXISTS tags(id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, name TEXT NOT NULL, UNIQUE(user_id,name));
CREATE TABLE IF NOT EXISTS item_tags(item_id TEXT NOT NULL REFERENCES items(id) ON DELETE CASCADE, tag_id TEXT NOT NULL REFERENCES tags(id) ON DELETE CASCADE, PRIMARY KEY(item_id,tag_id));
CREATE TABLE IF NOT EXISTS tasks(id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, title TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'open', priority TEXT NOT NULL DEFAULT 'normal', due_at TEXT, project_id TEXT REFERENCES projects(id) ON DELETE SET NULL, item_id TEXT REFERENCES items(id) ON DELETE SET NULL, completed_at TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_tasks_due ON tasks(user_id,status,due_at);
CREATE TABLE IF NOT EXISTS reminders(id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, title TEXT NOT NULL, note TEXT NOT NULL DEFAULT '', item_id TEXT REFERENCES items(id) ON DELETE SET NULL, task_id TEXT REFERENCES tasks(id) ON DELETE SET NULL, due_at TEXT NOT NULL, timezone TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'upcoming', snoozed_until TEXT, recurrence TEXT NOT NULL DEFAULT 'none', last_notified_at TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_reminders_due ON reminders(status,due_at);
CREATE TABLE IF NOT EXISTS notifications(id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, reminder_id TEXT REFERENCES reminders(id) ON DELETE CASCADE, occurrence TEXT NOT NULL, title TEXT NOT NULL, body TEXT NOT NULL, created_at TEXT NOT NULL, read_at TEXT, UNIQUE(reminder_id,occurrence));
CREATE TABLE IF NOT EXISTS conversations(id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, title TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS messages(id TEXT PRIMARY KEY, conversation_id TEXT NOT NULL REFERENCES conversations(id) ON DELETE CASCADE, role TEXT NOT NULL, content TEXT NOT NULL, mode TEXT NOT NULL DEFAULT 'retrieval', feedback INTEGER, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS citations(id TEXT PRIMARY KEY, message_id TEXT NOT NULL REFERENCES messages(id) ON DELETE CASCADE, item_id TEXT NOT NULL REFERENCES items(id) ON DELETE CASCADE, excerpt TEXT NOT NULL, relevance REAL NOT NULL, methods TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS relationships(id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, source_id TEXT NOT NULL REFERENCES items(id) ON DELETE CASCADE, target_id TEXT NOT NULL REFERENCES items(id) ON DELETE CASCADE, type TEXT NOT NULL, origin TEXT NOT NULL, confidence REAL NOT NULL DEFAULT 1, created_at TEXT NOT NULL, UNIQUE(source_id,target_id,type));
CREATE TABLE IF NOT EXISTS vault_connections(id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, name TEXT NOT NULL, root_path TEXT NOT NULL UNIQUE, includes TEXT NOT NULL, excludes TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'idle', last_sync TEXT, last_error TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS vault_notes(id TEXT PRIMARY KEY, connection_id TEXT NOT NULL REFERENCES vault_connections(id) ON DELETE CASCADE, item_id TEXT UNIQUE REFERENCES items(id) ON DELETE SET NULL, relative_path TEXT NOT NULL, stable_id TEXT, file_hash TEXT NOT NULL, imported_hash TEXT NOT NULL, obsidian_uri TEXT NOT NULL, last_synced_at TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'synced', UNIQUE(connection_id,relative_path));
CREATE INDEX IF NOT EXISTS idx_vault_hash ON vault_notes(connection_id,file_hash);
CREATE TABLE IF NOT EXISTS vault_logs(id TEXT PRIMARY KEY, connection_id TEXT REFERENCES vault_connections(id) ON DELETE CASCADE, kind TEXT NOT NULL, message TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS embedding_chunks(id TEXT PRIMARY KEY, item_id TEXT NOT NULL REFERENCES items(id) ON DELETE CASCADE, chunk_index INTEGER NOT NULL, text TEXT NOT NULL, embedding TEXT, model TEXT, content_hash TEXT NOT NULL, UNIQUE(item_id,chunk_index));
CREATE TABLE IF NOT EXISTS activities(id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, item_id TEXT REFERENCES items(id) ON DELETE CASCADE, action TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS saved_searches(id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, name TEXT NOT NULL, query TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS jobs(id TEXT PRIMARY KEY, item_id TEXT REFERENCES items(id) ON DELETE CASCADE, kind TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', attempts INTEGER NOT NULL DEFAULT 0, run_at TEXT NOT NULL, lease_at TEXT, error TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS runtime_state(key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE VIRTUAL TABLE IF NOT EXISTS items_fts USING fts5(item_id UNINDEXED, title, content, summary, personal_note, reason, tokenize='unicode61');
CREATE TRIGGER IF NOT EXISTS items_ai AFTER INSERT ON items BEGIN INSERT INTO items_fts(item_id,title,content,summary,personal_note,reason) VALUES(new.id,new.title,new.content,new.summary,new.personal_note,new.reason); END;
CREATE TRIGGER IF NOT EXISTS items_au AFTER UPDATE ON items BEGIN DELETE FROM items_fts WHERE item_id=old.id; INSERT INTO items_fts(item_id,title,content,summary,personal_note,reason) VALUES(new.id,new.title,new.content,new.summary,new.personal_note,new.reason); END;
CREATE TRIGGER IF NOT EXISTS items_ad AFTER DELETE ON items BEGIN DELETE FROM items_fts WHERE item_id=old.id; END;
